//
//  MarkdownExportView.swift
//  DailyFlightPlan
//
import SwiftUI

/// Presents Markdown generated by a caller (`RoutineView`, `CockpitView`, etc.), viewable as
/// either raw text or a rendered preview, with a one-tap copy and a `ShareLink` (AirDrop,
/// Messages, Save to Files, etc.) backed by a temp `.md` file.
struct MarkdownExportView: View {

    private enum ViewMode: String, CaseIterable {
        case preview = "Preview"
        case raw = "Raw"
    }

    var title: String
    let markdown: String

    @Environment(\.dismiss) private var dismiss
    @State private var didCopy = false
    @State private var viewMode: ViewMode = .preview

    private let exportFileURL: URL

    init(title: String, markdown: String) {
        self.title = title
        self.markdown = markdown
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("\(title).md")
        try? markdown.write(to: url, atomically: true, encoding: .utf8)
        self.exportFileURL = url
    }

    var body: some View {
        NavigationStack {
            Group {
                switch viewMode {
                case .preview: previewView
                case .raw: rawView
                }
            }
            .safeAreaInset(edge: .top) {
                Picker("View", selection: $viewMode) {
                    ForEach(ViewMode.allCases, id: \.self) { mode in
                        Text(mode.rawValue).tag(mode)
                    }
                }
                .pickerStyle(.segmented)
                .labelsHidden()
                .padding(.horizontal)
                .padding(.vertical, 8)
                .background(.bar)
            }
            .navigationTitle(title)
            .inlineNavigationTitle()
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Done") { dismiss() }
                }
                ToolbarItem(placement: .primaryAction) {
                    Button {
                        copyToClipboard()
                    } label: {
                        Label(didCopy ? "Copied" : "Copy", systemImage: didCopy ? "checkmark" : "doc.on.doc")
                    }
                }
                ToolbarItem(placement: .primaryAction) {
                    ShareLink(item: exportFileURL) {
                        Label("Share", systemImage: "square.and.arrow.up")
                    }
                }
            }
        }
        #if os(macOS)
        .frame(minWidth: 480, minHeight: 520)
        #endif
    }

    private var rawView: some View {
        ScrollView {
            Text(markdown)
                .font(.footnote.monospaced())
                .textSelection(.enabled)
                .frame(maxWidth: .infinity, alignment: .leading)
                .padding()
        }
    }

    // MARK: - Preview rendering

    /// A line-by-line renderer for the specific Markdown subset this app generates
    /// (`#`/`##`/`###`/`####` headers, `- ` bullets, `_italic_` placeholder lines, blank lines,
    /// plain text) — simpler and more predictable here than driving `Text`/`AttributedString`'s
    /// Markdown parsing, which doesn't apply block-level styling (heading size, bullets) on its own.
    private var previewView: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 6) {
                ForEach(Array(markdown.components(separatedBy: .newlines).enumerated()), id: \.offset) { _, line in
                    previewLine(line)
                }
            }
            .frame(maxWidth: .infinity, alignment: .leading)
            .padding()
            .textSelection(.enabled)
        }
    }

    @ViewBuilder
    private func previewLine(_ line: String) -> some View {
        if line.hasPrefix("#### ") {
            Text(String(line.dropFirst(5)))
                .font(.subheadline.bold())
                .padding(.top, 4)
        } else if line.hasPrefix("### ") {
            Text(String(line.dropFirst(4)))
                .font(.headline)
                .padding(.top, 6)
        } else if line.hasPrefix("## ") {
            Text(String(line.dropFirst(3)))
                .font(.title3.bold())
                .padding(.top, 10)
        } else if line.hasPrefix("# ") {
            Text(String(line.dropFirst(2)))
                .font(.title2.bold())
        } else if line.hasPrefix("- ") {
            HStack(alignment: .firstTextBaseline, spacing: 6) {
                Text("•").foregroundStyle(.secondary)
                Text(String(line.dropFirst(2)))
            }
            .font(.subheadline)
            .padding(.leading, 8)
        } else if line.hasPrefix("_") && line.hasSuffix("_") && line.count > 1 {
            Text(String(line.dropFirst().dropLast()))
                .font(.subheadline)
                .italic()
                .foregroundStyle(.secondary)
        } else if line.trimmingCharacters(in: .whitespaces).isEmpty {
            Color.clear.frame(height: 2)
        } else {
            Text(line)
                .font(.subheadline)
                .foregroundStyle(.secondary)
        }
    }

    private func copyToClipboard() {
        #if os(iOS) || os(visionOS)
        UIPasteboard.general.string = markdown
        #elseif os(macOS)
        NSPasteboard.general.clearContents()
        NSPasteboard.general.setString(markdown, forType: .string)
        #endif
        withAnimation { didCopy = true }
        Task {
            try? await Task.sleep(for: .seconds(1.5))
            withAnimation { didCopy = false }
        }
    }
}

